-- Owner "alpha" model "orgs"
CREATE TABLE IF NOT EXISTS "orgs" (
  "id" TEXT PRIMARY KEY,
  "slug" TEXT NOT NULL UNIQUE
);

-- Owner "alpha" model "members"
CREATE TABLE IF NOT EXISTS "members" (
  "id" TEXT PRIMARY KEY,
  "org_id" TEXT NOT NULL REFERENCES "orgs" ("id") ON DELETE CASCADE,
  "role" TEXT NOT NULL DEFAULT 'member',
  "seat_count" INTEGER NOT NULL DEFAULT 1,
  "spend_cap" DOUBLE PRECISION,
  "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "profile" JSONB,
  "notes" TEXT,
  "joined_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "offsite_ref" TEXT /* references elsewhere.id */
);

CREATE INDEX IF NOT EXISTS "members_org_id_idx" ON "members" ("org_id");

CREATE UNIQUE INDEX IF NOT EXISTS "members_org_id_role_unique" ON "members" ("org_id", "role");

-- Owner "beta" model "projects"
