  "id" TEXT PRIMARY KEY,
  "projectTitle" TEXT NOT NULL,
  "ownerId" TEXT NOT NULL REFERENCES "tickets" ("id"),
  "createdAt" TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS "projects_ownerId_idx" ON "projects" ("ownerId");

-- Owner "beta" model "tickets"
